# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_scoop_alias() {
    scoop alias list 2>/dev/null | _argc_util_transform_table 'Name'
}

_choice_scoop_app() {
    local root file name
    root="$(_helper_scoop_root)"
    [[ -n "$root" ]] || return 0
    if [[ -d "$root/buckets" ]]; then
        for file in "$root"/buckets/*/bucket/*.json; do
            [[ -f "$file" ]] || continue
            name="${file##*/}"
            printf '%s\n' "${name%.json}"
        done
    fi
    _choice_scoop_installed_app
}

_choice_scoop_bucket() {
    local root dir name
    root="$(_helper_scoop_root)"
    [[ -n "$root" && -d "$root/buckets" ]] || return 0
    for dir in "$root"/buckets/*; do
        [[ -d "$dir" ]] || continue
        name="${dir##*/}"
        printf '%s\n' "$name"
    done
}

_choice_scoop_installed_app() {
    local root dir name
    root="$(_helper_scoop_root)"
    [[ -n "$root" && -d "$root/apps" ]] || return 0
    for dir in "$root"/apps/*; do
        [[ -d "$dir" ]] || continue
        name="${dir##*/}"
        printf '%s\n' "$name"
    done
}

_choice_scoop_known_bucket() {
    scoop bucket known 2>/dev/null
}

_choice_scoop_shim() {
    local root file name
    root="$(_helper_scoop_root)"
    [[ -n "$root" && -d "$root/shims" ]] || return 0
    for file in "$root"/shims/*; do
        [[ -f "$file" ]] || continue
        name="${file##*/}"
        case "$name" in
        *.shim) ;;
        *.exe | *.com | *.bat | *.cmd | *.ps1 | *.sh) printf '%s\n' "${name%.*}" ;;
        *) printf '%s\n' "$name" ;;
        esac
    done
}

_helper_scoop_root() {
    local shim
    if [[ -n "${SCOOP:-}" ]]; then
        shim="${SCOOP%/apps/scoop/current}"
        if [[ -d "$shim" && ( -d "$shim/buckets" || -d "$shim/apps" ) ]]; then
            printf '%s\n' "$shim"
            return 0
        fi
    fi
    shim="$(command -v scoop 2>/dev/null)" || return 0
    shim="${shim//\\//}"
    case "$shim" in
    */shims/*) printf '%s\n' "${shim%/shims/*}" ;;
    *)
        shim="${shim%/*}"
        printf '%s\n' "${shim%/*}"
        ;;
    esac
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
